mod solution;

fn main() {
    let cases = [
    (r#"edges=0-1:1,0-2:4,1-2:2,1-3:5,2-3:3"#, r#"1,2,3"#),
    (r#"edges=0-1:2,1-2:3,0-2:10"#, r#"2,3"#),
    (r#"
edges=0-1:2,1-2:3,0-2:10
"#, r#"2,3"#),
    (r#"  
edges=0-1:1,0-2:4,1-2:2,1-3:5,2-3:3
  "#, r#"1,2,3"#),
    ];
    for (case_index, (input, expected)) in cases.iter().enumerate() {
        if solution::solve(input) != *expected {
            eprintln!("PRIVATE CASE {} FAILED", case_index + 1);
            std::process::exit(1);
        }
    }
    println!("PASS kruskal-mst");
}
